//! Decode real mstsc RDP-UDP2 datagrams captured on the wire (tcpdump) with
//! this crate's own decoder, so the parser and the wire stay honest.

use ironrdp_core::decode;
use ironrdp_rdpeudp::pdu::{decode_with_prefix, V2Packet};

const CASES: &[(u32, &str, usize)] = &[
        (1, "", 430),
        (2, "", 1007),
        (3, "", 427),
        (4, "", 427),
        (5, "0014f26c006d00f0000000", 11),
];

#[test]
fn decode_captured_mstsc_packets() {
    for (n, hex, len) in CASES {
        let mut wire = alloc_hex(hex);
        let (prefix, packet_bytes) = decode_with_prefix(&mut wire)
            .unwrap_or_else(|e| panic!("case {n}: prefix decode failed: {e:?}"));
        let packet: V2Packet = decode(packet_bytes)
            .unwrap_or_else(|e| panic!("case {n}: V2Packet decode failed: {e:?}"));
        println!(
            "case {n} ({len} B): prefix={prefix:?}\n  header={:?}\n  ack={:?}\n  ack_vector={:?}\n  data_header={:?} data_body_len={}",
            packet.header, packet.ack, packet.ack_vector,
            packet.data_header, packet.data_body.is_some()
        );
    }
}

fn alloc_hex(hex: &str) -> Vec<u8> {
    (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).expect("hex byte"))
        .collect()
}
